import{_ as t}from"./chunks/team-access.Nfq-hDXJ.js";import{_ as n,o as a,c as s,a3 as r}from"./chunks/framework.CchDE9cb.js";const y=JSON.parse(`{"title":"Roles and permissions","description":"What each of CapacityLens's four roles can see and do, and how sign-in, membership and the schedule stay separate.","frontmatter":{"title":"Roles and permissions","description":"What each of CapacityLens's four roles can see and do, and how sign-in, membership and the schedule stay separate."},"headers":[],"relativePath":"getting-started/roles-and-permissions.md","filePath":"getting-started/roles-and-permissions.md","lastUpdated":null}`),i={name:"getting-started/roles-and-permissions.md"};function o(d,e,l,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and permissions&quot;">​</a></h1><p>CapacityLens has four roles, strictly nested: <strong>Viewer &lt; Editor &lt; <a href="/capacitylens/reference/glossary">Admin</a> &lt; <a href="/capacitylens/reference/glossary">Owner</a></strong>. Every <a href="/capacitylens/reference/glossary">member</a> gets the same navigation — a role changes what&#39;s editable and visible inside each page, and that&#39;s enforced on the server, not just hidden in the interface. This page explains what each role can do and clears up a common point of confusion: the difference between having a sign-in, being a member of a company, and being on the schedule.</p><h2 id="the-three-kinds-of-person" tabindex="-1">The three kinds of &quot;person&quot; <a class="header-anchor" href="#the-three-kinds-of-person" aria-label="Permalink to &quot;The three kinds of &quot;person&quot;&quot;">​</a></h2><p>CapacityLens keeps three things separate that can all look like &quot;a <a href="/capacitylens/reference/glossary">person</a>&quot; in the interface:</p><ul><li>A <strong>sign-in identity</strong> — the email and password (or company login) someone uses to reach CapacityLens at all. One identity can belong to several companies.</li><li>A <strong>member</strong> — a sign-in identity&#39;s role in one specific company, created by <a href="/capacitylens/getting-started/invite-your-team">inviting them</a>. This controls what they can see and do in that company.</li><li>A <strong>person</strong> on the schedule — a schedulable resource that can receive allocations and time off. Adding a person doesn&#39;t give them a sign-in, and inviting a member doesn&#39;t put them on the schedule.</li></ul><p>Most agencies end up with a few members and many people: you schedule freelancers and contractors without ever creating a sign-in for them. See the <a href="/capacitylens/reference/glossary">glossary</a> for precise definitions of these and other terms used throughout these docs.</p><h2 id="roles-in-one-table" tabindex="-1">Roles in one table <a class="header-anchor" href="#roles-in-one-table" aria-label="Permalink to &quot;Roles in one table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th style="text-align:center;">Viewer</th><th style="text-align:center;">Editor</th><th style="text-align:center;">Admin</th><th style="text-align:center;">Owner</th></tr></thead><tbody><tr><td>See the schedule</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>Create and edit scheduling data</td><td style="text-align:center;">—</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>Change ordinary company settings</td><td style="text-align:center;">—</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>See time-off notes</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>See private client/project real names</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">Yes</td></tr><tr><td>List members and manage invites</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">Yes</td><td style="text-align:center;">Yes</td></tr><tr><td>Export the schedule</td><td style="text-align:center;">Redacted</td><td style="text-align:center;">Redacted</td><td style="text-align:center;">Full</td><td style="text-align:center;">Full</td></tr><tr><td>Import, delete the company, transfer ownership</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">Yes</td></tr></tbody></table><p>There is exactly one Owner per company, and Owner can&#39;t be assigned through an invite or an ordinary role change — only through an explicit ownership transfer to an existing member. An Admin can invite, remove or change the role of any other member, but can&#39;t touch the Owner. If a company somehow ends up with no Owner at all, see <a href="/capacitylens/self-hosting/incidents#a-company-has-no-owner">A company has no Owner</a> — CapacityLens repairs that automatically in almost every case.</p><p><img src="'+t+'" alt="The Team &amp; access page, where an Admin or Owner sees each member&#39;s role and manages invites"></p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><p><strong>Export.</strong> An export is redacted the same way the screen is:</p><table tabindex="0"><thead><tr><th>What the export contains</th><th>Viewer / Editor</th><th>Admin</th><th>Owner</th></tr></thead><tbody><tr><td>Archived and deleted rows</td><td>Left out</td><td>Included</td><td>Included</td></tr><tr><td>Private client/project names</td><td>Code names</td><td>Code names</td><td>Real names</td></tr></tbody></table><p>So an Admin&#39;s export holds the full set of rows, but only an Owner&#39;s export contains the real private client and project names.</p><p><strong>Offline snapshots.</strong> <a href="/capacitylens/guide/offline-access">Offline access</a> always behaves like a Viewer, no matter your real role — while a cached snapshot is shown, creating, editing, deleting, importing and changing membership are all unavailable for everyone. The snapshot reflects whatever that person could see the last time they were online: a non-owner&#39;s snapshot uses code names, while an owner&#39;s may contain real private names — so protect an owner&#39;s device accordingly.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>You&#39;ve now covered sign-in, installing, first steps, invites and roles. Head to <a href="/capacitylens/guide/the-schedule">The schedule</a> to start building out your team&#39;s week.</p>',17)])])}const u=n(i,[["render",o]]);export{y as __pageData,u as default};
